def is_regular_bracket_sequence(s):
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack[-1] != '(':
                return False
            stack.pop()
    return not stack

def find_shortest_regular_bracket_sequence(s, t):
    # Find the longest common subsequence of s and t
    n, m = len(s), len(t)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs = dp[n][m]

    # Reconstruct the shortest regular bracket sequence
    result = []
    i, j = 0, 0
    while len(result) < lcs:
        if i < n and j < m and s[i] == t[j]:
            result.append(s[i])
            i += 1
            j += 1
        elif i < n and (j >= m or dp[i + 1][j] >= dp[i][j + 1]):
            result.append(s[i])
            i += 1
        else:
            result.append(t[j])
            j += 1

    # Complete the bracket sequence to be regular
    stack = []
    for char in result:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack and stack[-1] == '(':
                stack.pop()
            else:
                stack.append(char)

    while stack:
        result += '(' if stack.pop() == ')' else ')'

    return ''.join(result)

